// Hot batch 242: sixty- to sixty-one-instruction functions no route reaches, written by hand from `tools.disasm` and verified
// by synthetic cases (quaternion products, sorted inserts, pointer-to-member calls and record copies).
// No names: none has evidence.
#include "decomp_registry.hpp"
#include "gt/game/hot_common.hpp"
